import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# ---------- elementwise addition custom CUDA operator ----------
elementwise_add_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void elementwise_add_kernel(const float* a, const float* b, float* out, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        out[idx] = a[idx] + b[idx];
    }
}

torch::Tensor elementwise_add_cuda(torch::Tensor a, torch::Tensor b) {
    auto size = a.numel();
    auto out = torch::zeros_like(a);

    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    elementwise_add_kernel<<<num_blocks, block_size>>>(a.data_ptr<float>(), b.data_ptr<float()>, out.data_ptr<float()>, size);

    return out;
}
"""

elementwise_add_cpp_source = "torch::Tensor elementwise_add_cuda(torch::Tensor a, torch::Tensor b);"

elementwise_add = load_inline(
    name="elementwise_add",
    cpp_sources=elementwise_add_cpp_source,
    cuda_sources=elementwise_add_source,
    functions=["elementwise_add_cuda"],
    verbose=True
)

# ---------- matrix multiplication custom CUDA operator ----------
matmul_cpp_source = "torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B);"

matmul_kernel_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void matmul_kernel(const float* A, const float* B, float* C, int K, int M_rows, int N_cols) {
    long long idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= M_rows * N_cols) return;

    int row = idx / N_cols;
    int col = idx % N_cols;
    float sum = 0.0f;
    for (int k = 0; k < K; ++k) {
        // A[k, row] and B[k, col]
        sum += A[k * M_rows + row] * B[k * N_cols + col];
    }
    C[idx] = sum;
}

torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B) {
    auto M_rows = A.size(1);
    auto K = A.size(0);
    auto N_cols = B.size(1);

    auto out = torch::zeros({M_rows, N_cols}, dtype=A.dtype);

    const int block_size = 256;
    const int num_blocks = (M_rows * N_cols + block_size - 1) / block_size;

    matmul_kernel<<<num_blocks, block_size>>>(A.data_ptr<float>(), B.data_ptr<float()>, out.data_ptr<float()>, K, M_rows, N_cols);

    return out;
}
"""

matmul_cuda = load_inline(
    name="matmul_cuda",
    cpp_sources=matmul_cpp_source,
    cuda_sources=matmul_kernel_source,
    functions=["matmul_cuda"],
    verbose=True
)

# ---------- Optimized model ----------
class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()
        self.elementwise_add = elementwise_add
        self.matmul_cuda = matmul_cuda

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        """
        Performs matrix multiplication C = A^T @ B.
        Input shapes:
            A: (K, M)
            B: (K, N)
        Output shape: (M, N).
        """
        return self.matmul_cuda(A, B)
